joi.script:
if ((#AirQualitySensor #Warehouse).airQualitySensor_fineDustLevel >= 100 and (#AirPurifier #Warehouse).airPurifier_airPurifierMode == "auto") {
(#AirPurifier #Warehouse).airPurifier_setAirPurifierMode("high")
all(#Speaker).speaker_speak("Switching to high mode")
}

if ((#Entrance).motionSensor_motion == true or (#Balcony).motionSensor_motion == true) {
(#LivingRoom).speaker_speak("Motion is detected at the entrance or motion is detected on the balcony")
}

triggered := false
if (all(#ContactSensor).contactSensor_contact ==| false) {
if (triggered == false) {
(#Hall_Light_1).switch_on()
(#Hall_Light_2).switch_on()
(#LR_Light_1).switch_on()
(#LR_Light_2).switch_on()
        triggered = true
}
}
else {
triggered = false
}

phase := 0
if (phase == 0) {
wait until((#LivingRoom #SmokeDetector).smokeDetector_smoke == true)
    phase = 1
    all(#LivingRoom #Siren).siren_setSirenMode("fire")
}
else {
all(#Speaker).speaker_speak("Please evacuate")
}

phase := 0
if (phase == 0) {
wait until(all(#Floor1 #PresenceSensor).presenceSensor_presence ==| true)
    phase = 1
    all(#Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
all(#Siren).switch_off()
}
else {
all(#Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
all(#Siren).switch_off()
}

n := 0
triggered := false
if ((#LivingRoom #MultiButton).multiButton_button4 == "pushed") {
if (triggered == false) {
if (n % 3 == 0) {
all(#Light #LivingRoom).light_moveToBrightness(25.0, 0.0)
}
else {
if (n % 3 == 1) {
all(#Light #LivingRoom).light_moveToBrightness(50.0, 0.0)
}
else {
all(#Light #LivingRoom).light_moveToBrightness(75.0, 0.0)
}
}
triggered = true
}
}
else {
triggered = false
}
n = n + 1

hold_ticks := 0
if ((#LivingRoom #PresenceSensor).presenceSensor_presence == true) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 30) {
(#Plug).switch_on()
        break
}
}
else {
hold_ticks = 0
}

hold_ticks := 0
if ((#TV).charger_power < 10) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 900) {
(#TV).switch_off()
        break
}
}
else {
hold_ticks = 0
}

if ((all(#Bedroom).motionSensor_motion ==| true or all(#Bedroom).motionSensor_motion ==| true)) {
(#Speaker).speaker_speak("Motion detected in the living room or bedroom.")
}

n := 0
if (n >= 3) {
break
}
all(#Speaker).speaker_speak("lunch time")
n = n + 1

hold_ticks := 0
if ((#Plug).plug_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 600) {
n := 0
        if (n >= 3) {
break
}
(#Speaker).speaker_speak("Device is idle")
        n = n + 1
}
}
else {
hold_ticks = 0
}
n = n + 1

wait until((all(#RobotVacuumCleaner).robotVacuumCleaner_robotVacuumCleanerOperatingState ==| "running"))
wait until((all(#RobotVacuumCleaner).robotVacuumCleaner_robotVacuumCleanerOperatingState ==| "docked"))
if (true) {
(#Speaker).speaker_speak("The robot vacuum cleaner is stuck")
}
